        public enum FailedBody {
            /// "Photo suggestions are not set up on this phone."
            public static var not_configured: String { L10nRuntime.text("suggestions.failedBody.not_configured", "Photo suggestions are not set up on this phone.") }
            /// "There is no connection, so there are no suggestions."
