            /// "Suggestions are not available right now."
            public static var server_error: String { L10nRuntime.text("suggestions.failedBody.server_error", "Suggestions are not available right now.") }
            /// "The suggestion could not be read."
            public static var malformed_response: String { L10nRuntime.text("suggestions.failedBody.malformed_response", "The suggestion could not be read.") }
            /// "This version of the app cannot read suggestions. Update the app."
            public static var unsupported_version: String { L10nRuntime.text("suggestions.failedBody.unsupported_version", "This version of the app cannot read suggestions. Update the app.") }
            /// "The photo was not clear enough for a guess."
            public static var low_confidence: String { L10nRuntime.text("suggestions.failedBody.low_confidence", "The photo was not clear enough for a guess.") }
            /// "The item in the photo could not be recognised."
            public static var unrecognized: String { L10nRuntime.text("suggestions.failedBody.unrecognized", "The item in the photo could not be recognised.") }
            /// The keys, in strings.ts order.
            public static let allKeys: [String] = ["not_configured", "offline", "timeout", "rate_limited", "server_error", "malformed_response", "unsupported_version", "low_confidence", "unrecognized"]
            /// The value for `key`, or nil when strings.ts has no such key. The match is exact, as in JS.
            public static subscript(key: String) -> String? {
                if L10nRuntime.same(key, "not_configured") { return not_configured }
                if L10nRuntime.same(key, "offline") { return offline }
                if L10nRuntime.same(key, "timeout") { return timeout }
                if L10nRuntime.same(key, "rate_limited") { return rate_limited }
                if L10nRuntime.same(key, "server_error") { return server_error }
                if L10nRuntime.same(key, "malformed_response") { return malformed_response }
                if L10nRuntime.same(key, "unsupported_version") { return unsupported_version }
                if L10nRuntime.same(key, "low_confidence") { return low_confidence }
                if L10nRuntime.same(key, "unrecognized") { return unrecognized }
                return nil
            }
        }

        /// "Try suggestions again"
        public static var retry: String { L10nRuntime.text("suggestions.retry", "Try suggestions again") }
    }

