extension Format {
    /// Catalog entries behind `ago(_:now:)` (spec 08 §3.3).
    enum AgoKeys {
        /// "just now"
        static var justNow: String { L10nRuntime.text("format.ago.justNow", "just now") }

        /// "yesterday"
        static var yesterday: String { L10nRuntime.text("format.ago.yesterday", "yesterday") }

        /// "{count} minutes ago"
        static func minutes(count: Int) -> String {
            L10nRuntime.plural("format.ago.minutes", one: "%lld minute ago", other: "%lld minutes ago", count)
        }

        /// "{count} hours ago"
        static func hours(count: Int) -> String {
            L10nRuntime.plural("format.ago.hours", one: "%lld hour ago", other: "%lld hours ago", count)
        }

        /// "{count} days ago"
        static func days(count: Int) -> String {
            L10nRuntime.plural("format.ago.days", one: "%lld day ago", other: "%lld days ago", count)
        }

        /// "{count} months ago"
        static func months(count: Int) -> String {
            L10nRuntime.plural("format.ago.months", one: "%lld month ago", other: "%lld months ago", count)
        }

        /// "{count} years ago"
        static func years(count: Int) -> String {
            L10nRuntime.plural("format.ago.years", one: "%lld year ago", other: "%lld years ago", count)
        }
    }
}
